window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-810fd0bcc4cdbc54"]={"versions": [{"id": "FIG-810fd0bcc4cdbc54", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Schichtenarchitektur im Kommunikations- und Diagnose-Stack.</li>\n<li><strong>Funktionale Einordnung:</strong> Direkte PDU-Empfangsschnittstelle des XCP-Moduls über das FlexRay-Interface (<code>FrIf</code>) unter Umgehung des <code>PduR</code> (FlexRay-Transport-Layer-Bindung <code>XcpOnFr</code>). Visualisiert die synchrone Entgegennahme und Pufferung einer eingehenden XCP-Nachricht (CTO/DTO) aus dem FlexRay-Kommunikationszyklus.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Instanzen (Lifelines):</strong></li>\n<li><code>FrIf :FrIf</code>: FlexRay Interface (Communication Hardware Abstraction Layer). Agiert als Aufrufer/Trigger bei Empfang eines FlexRay-Frames bzw. einer LPDU.</li>\n<li><code>XcpOnFr :Xcp</code>: XCP-Modul (Services Layer / Complex Drivers / Transport Layer). Empfänger und Verarbeiter des XCP-Protokoll-Frames.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li><code>Xcp_FrIfRxIndication(PduIdType, const uint8*)</code>:</li>\n<li><code>PduIdType</code>: Konfigurierte Ziel-PDU-ID (<code>RxPduId</code>) zur Identifikation des logischen XCP-Kanals / Frame-Typs.</li>\n<li><code>const uint8*</code>: Zeiger auf die Nutzdaten (SDU-Payload) im Speicherbereich des FlexRay-Treibers bzw. Interfaces.</li>\n<li><strong>Interne Operationen:</strong></li>\n<li><code>Copy PDU to internal location and process PDU()</code>: Lokale Pufferoperation und Protokollparsing innerhalb der XCP-Engine.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>FrIf</code> stellt das Vorliegen einer für XCP bestimmten PDU fest (z. B. im Rahmen von <code>FrIf_MainFunction_RouteRx()</code> oder eines Rx-Interrupt-Handlings).</li>\n<li><strong>Synchroner Callback:</strong> <code>FrIf</code> ruft synchron <code>Xcp_FrIfRxIndication(PduIdType, const uint8*)</code> auf <code>XcpOnFr</code> auf.</li>\n<li><strong>Pufferung & Verarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>XcpOnFr</code> kopiert die Nutzdaten (<code>SDU</code>) synchron in einen internen Puffer (<code>Copy PDU to internal location</code>), da der übergebene Zeiger nur für die Dauer des Funktionsaufrufs gültig ist.</li>\n<li><code>XcpOnFr</code> stößt die PDU-Interpretation (Kommando-Dekodierung bei CTO bzw. Messdaten-Handling bei STIM) an (<code>process PDU()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rückkehr:</strong> <code>Xcp_FrIfRxIndication()</code> kehrt synchron zu <code>FrIf</code> zurück (gestrichelte Rückkehrkante), wodurch der Rx-Puffer im <code>FrIf</code>/Treiber wieder zur Wiederverwendung freigegeben wird.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicherlebensdauer & Pufferverwaltung:</strong> Der von <code>FrIf</code> übergebene Datenzeiger (<code>const uint8*</code>) ist flüchtig. Treiber- und Stack-Entwickler müssen sicherstellen, dass die Daten zwingend innerhalb des Aufrufs kopiert werden; eine asynchrone Referenzierung des Zeigers führt zu Data Corruptions.</li>\n<li><strong>Ausführungskontext & Latenz:</strong> Der Aufruf erfolgt je nach FlexRay-Konfiguration im Interrupt-Kontext oder im Kontext einer zyklischen Task (<code>FrIf_MainFunction</code>). Um den FlexRay-Buszyklus nicht zu blockieren, muss die PDU-Kopieroperation atomar und minimal gehalten werden; rechenintensive XCP-Befehle (z. B. Flash-Programmierung) müssen entkoppelt in der <code>Xcp_MainFunction()</code> abgearbeitet werden.</li>\n<li><strong>Konfigurationsbindung:</strong> In der AUTOSAR-Konfiguration (<code>EcucPostBuildType</code> / XML) muss die vom <code>FrIf</code> gemappte PDU als Rx-Referenz exakt auf die konfigurierte <code>XcpRxPduId</code> abgestimmt sein (<code>FrIfRxPduUserRxIndicationUL = XCP</code>).</li>\n</ul>"}, {"id": "FIG-c7636a81bae2763c", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Schichtenarchitektur im Kommunikations- und Diagnose-Stack.</li>\n<li><strong>Funktionale Einordnung:</strong> Direkte PDU-Empfangsschnittstelle des XCP-Moduls über das FlexRay-Interface (<code>FrIf</code>) unter Umgehung des <code>PduR</code> (FlexRay-Transport-Layer-Bindung <code>XcpOnFr</code>). Visualisiert die synchrone Entgegennahme und Pufferung einer eingehenden XCP-Nachricht (CTO/DTO) aus dem FlexRay-Kommunikationszyklus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Instanzen (Lifelines):</strong></li>\n<li><code>FrIf :FrIf</code>: FlexRay Interface (Communication Hardware Abstraction Layer). Agiert als Aufrufer/Trigger bei Empfang eines FlexRay-Frames bzw. einer LPDU.</li>\n<li><code>XcpOnFr :Xcp</code>: XCP-Modul (Services Layer / Complex Drivers / Transport Layer). Empfänger und Verarbeiter des XCP-Protokoll-Frames.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li><code>Xcp_FrIfRxIndication(PduIdType, const uint8*)</code>:</li>\n<li><code>PduIdType</code>: Konfigurierte Ziel-PDU-ID (<code>RxPduId</code>) zur Identifikation des logischen XCP-Kanals / Frame-Typs.</li>\n<li><code>const uint8*</code>: Zeiger auf die Nutzdaten (SDU-Payload) im Speicherbereich des FlexRay-Treibers bzw. Interfaces.</li>\n<li><strong>Interne Operationen:</strong></li>\n<li><code>Copy PDU to internal location and process PDU()</code>: Lokale Pufferoperation und Protokollparsing innerhalb der XCP-Engine.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>FrIf</code> stellt das Vorliegen einer für XCP bestimmten PDU fest (z. B. im Rahmen von <code>FrIf_MainFunction_RouteRx()</code> oder eines Rx-Interrupt-Handlings).</li>\n<li><strong>Synchroner Callback:</strong> <code>FrIf</code> ruft synchron <code>Xcp_FrIfRxIndication(PduIdType, const uint8*)</code> auf <code>XcpOnFr</code> auf.</li>\n<li><strong>Pufferung & Verarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>XcpOnFr</code> kopiert die Nutzdaten (<code>SDU</code>) synchron in einen internen Puffer (<code>Copy PDU to internal location</code>), da der übergebene Zeiger nur für die Dauer des Funktionsaufrufs gültig ist.</li>\n<li><code>XcpOnFr</code> stößt die PDU-Interpretation (Kommando-Dekodierung bei CTO bzw. Messdaten-Handling bei STIM) an (<code>process PDU()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rückkehr:</strong> <code>Xcp_FrIfRxIndication()</code> kehrt synchron zu <code>FrIf</code> zurück (gestrichelte Rückkehrkante), wodurch der Rx-Puffer im <code>FrIf</code>/Treiber wieder zur Wiederverwendung freigegeben wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicherlebensdauer & Pufferverwaltung:</strong> Der von <code>FrIf</code> übergebene Datenzeiger (<code>const uint8*</code>) ist flüchtig. Treiber- und Stack-Entwickler müssen sicherstellen, dass die Daten zwingend innerhalb des Aufrufs kopiert werden; eine asynchrone Referenzierung des Zeigers führt zu Data Corruptions.</li>\n<li><strong>Ausführungskontext & Latenz:</strong> Der Aufruf erfolgt je nach FlexRay-Konfiguration im Interrupt-Kontext oder im Kontext einer zyklischen Task (<code>FrIf_MainFunction</code>). Um den FlexRay-Buszyklus nicht zu blockieren, muss die PDU-Kopieroperation atomar und minimal gehalten werden; rechenintensive XCP-Befehle (z. B. Flash-Programmierung) müssen entkoppelt in der <code>Xcp_MainFunction()</code> abgearbeitet werden.</li>\n<li><strong>Konfigurationsbindung:</strong> In der AUTOSAR-Konfiguration (<code>EcucPostBuildType</code> / XML) muss die vom <code>FrIf</code> gemappte PDU als Rx-Referenz exakt auf die konfigurierte <code>XcpRxPduId</code> abgestimmt sein (<code>FrIfRxPduUserRxIndicationUL = XCP</code>).</li>\n</ul>"}, {"id": "FIG-9981e87515a3a421", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Schichtenarchitektur im Kommunikations- und Diagnose-Stack.</li>\n<li><strong>Funktionale Einordnung:</strong> Direkte PDU-Empfangsschnittstelle des XCP-Moduls über das FlexRay-Interface (<code>FrIf</code>) unter Umgehung des <code>PduR</code> (FlexRay-Transport-Layer-Bindung <code>XcpOnFr</code>). Visualisiert die synchrone Entgegennahme und Pufferung einer eingehenden XCP-Nachricht (CTO/DTO) aus dem FlexRay-Kommunikationszyklus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Instanzen (Lifelines):</strong></li>\n<li><code>FrIf :FrIf</code>: FlexRay Interface (Communication Hardware Abstraction Layer). Agiert als Aufrufer/Trigger bei Empfang eines FlexRay-Frames bzw. einer LPDU.</li>\n<li><code>XcpOnFr :Xcp</code>: XCP-Modul (Services Layer / Complex Drivers / Transport Layer). Empfänger und Verarbeiter des XCP-Protokoll-Frames.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li><code>Xcp_FrIfRxIndication(PduIdType, const uint8*)</code>:</li>\n<li><code>PduIdType</code>: Konfigurierte Ziel-PDU-ID (<code>RxPduId</code>) zur Identifikation des logischen XCP-Kanals / Frame-Typs.</li>\n<li><code>const uint8*</code>: Zeiger auf die Nutzdaten (SDU-Payload) im Speicherbereich des FlexRay-Treibers bzw. Interfaces.</li>\n<li><strong>Interne Operationen:</strong></li>\n<li><code>Copy PDU to internal location and process PDU()</code>: Lokale Pufferoperation und Protokollparsing innerhalb der XCP-Engine.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>FrIf</code> stellt das Vorliegen einer für XCP bestimmten PDU fest (z. B. im Rahmen von <code>FrIf_MainFunction_RouteRx()</code> oder eines Rx-Interrupt-Handlings).</li>\n<li><strong>Synchroner Callback:</strong> <code>FrIf</code> ruft synchron <code>Xcp_FrIfRxIndication(PduIdType, const uint8*)</code> auf <code>XcpOnFr</code> auf.</li>\n<li><strong>Pufferung & Verarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>XcpOnFr</code> kopiert die Nutzdaten (<code>SDU</code>) synchron in einen internen Puffer (<code>Copy PDU to internal location</code>), da der übergebene Zeiger nur für die Dauer des Funktionsaufrufs gültig ist.</li>\n<li><code>XcpOnFr</code> stößt die PDU-Interpretation (Kommando-Dekodierung bei CTO bzw. Messdaten-Handling bei STIM) an (<code>process PDU()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rückkehr:</strong> <code>Xcp_FrIfRxIndication()</code> kehrt synchron zu <code>FrIf</code> zurück (gestrichelte Rückkehrkante), wodurch der Rx-Puffer im <code>FrIf</code>/Treiber wieder zur Wiederverwendung freigegeben wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicherlebensdauer & Pufferverwaltung:</strong> Der von <code>FrIf</code> übergebene Datenzeiger (<code>const uint8*</code>) ist flüchtig. Treiber- und Stack-Entwickler müssen sicherstellen, dass die Daten zwingend innerhalb des Aufrufs kopiert werden; eine asynchrone Referenzierung des Zeigers führt zu Data Corruptions.</li>\n<li><strong>Ausführungskontext & Latenz:</strong> Der Aufruf erfolgt je nach FlexRay-Konfiguration im Interrupt-Kontext oder im Kontext einer zyklischen Task (<code>FrIf_MainFunction</code>). Um den FlexRay-Buszyklus nicht zu blockieren, muss die PDU-Kopieroperation atomar und minimal gehalten werden; rechenintensive XCP-Befehle (z. B. Flash-Programmierung) müssen entkoppelt in der <code>Xcp_MainFunction()</code> abgearbeitet werden.</li>\n<li><strong>Konfigurationsbindung:</strong> In der AUTOSAR-Konfiguration (<code>EcucPostBuildType</code> / XML) muss die vom <code>FrIf</code> gemappte PDU als Rx-Referenz exakt auf die konfigurierte <code>XcpRxPduId</code> abgestimmt sein (<code>FrIfRxPduUserRxIndicationUL = XCP</code>).</li>\n</ul>"}, {"id": "FIG-0c98b8e590b59800", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Schichtenarchitektur im Kommunikations- und Diagnose-Stack.</li>\n<li><strong>Funktionale Einordnung:</strong> Direkte PDU-Empfangsschnittstelle des XCP-Moduls über das FlexRay-Interface (<code>FrIf</code>) unter Umgehung des <code>PduR</code> (FlexRay-Transport-Layer-Bindung <code>XcpOnFr</code>). Visualisiert die synchrone Entgegennahme und Pufferung einer eingehenden XCP-Nachricht (CTO/DTO) aus dem FlexRay-Kommunikationszyklus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Instanzen (Lifelines):</strong></li>\n<li><code>FrIf :FrIf</code>: FlexRay Interface (Communication Hardware Abstraction Layer). Agiert als Aufrufer/Trigger bei Empfang eines FlexRay-Frames bzw. einer LPDU.</li>\n<li><code>XcpOnFr :Xcp</code>: XCP-Modul (Services Layer / Complex Drivers / Transport Layer). Empfänger und Verarbeiter des XCP-Protokoll-Frames.</li>\n<li><strong>Schnittstellen & Parameter:</strong></li>\n<li><code>Xcp_FrIfRxIndication(PduIdType, const uint8*)</code>:</li>\n<li><code>PduIdType</code>: Konfigurierte Ziel-PDU-ID (<code>RxPduId</code>) zur Identifikation des logischen XCP-Kanals / Frame-Typs.</li>\n<li><code>const uint8*</code>: Zeiger auf die Nutzdaten (SDU-Payload) im Speicherbereich des FlexRay-Treibers bzw. Interfaces.</li>\n<li><strong>Interne Operationen:</strong></li>\n<li><code>Copy PDU to internal location and process PDU()</code>: Lokale Pufferoperation und Protokollparsing innerhalb der XCP-Engine.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>FrIf</code> stellt das Vorliegen einer für XCP bestimmten PDU fest (z. B. im Rahmen von <code>FrIf_MainFunction_RouteRx()</code> oder eines Rx-Interrupt-Handlings).</li>\n<li><strong>Synchroner Callback:</strong> <code>FrIf</code> ruft synchron <code>Xcp_FrIfRxIndication(PduIdType, const uint8*)</code> auf <code>XcpOnFr</code> auf.</li>\n<li><strong>Pufferung & Verarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>XcpOnFr</code> kopiert die Nutzdaten (<code>SDU</code>) synchron in einen internen Puffer (<code>Copy PDU to internal location</code>), da der übergebene Zeiger nur für die Dauer des Funktionsaufrufs gültig ist.</li>\n<li><code>XcpOnFr</code> stößt die PDU-Interpretation (Kommando-Dekodierung bei CTO bzw. Messdaten-Handling bei STIM) an (<code>process PDU()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Rückkehr:</strong> <code>Xcp_FrIfRxIndication()</code> kehrt synchron zu <code>FrIf</code> zurück (gestrichelte Rückkehrkante), wodurch der Rx-Puffer im <code>FrIf</code>/Treiber wieder zur Wiederverwendung freigegeben wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicherlebensdauer & Pufferverwaltung:</strong> Der von <code>FrIf</code> übergebene Datenzeiger (<code>const uint8*</code>) ist flüchtig. Treiber- und Stack-Entwickler müssen sicherstellen, dass die Daten zwingend innerhalb des Aufrufs kopiert werden; eine asynchrone Referenzierung des Zeigers führt zu Data Corruptions.</li>\n<li><strong>Ausführungskontext & Latenz:</strong> Der Aufruf erfolgt je nach FlexRay-Konfiguration im Interrupt-Kontext oder im Kontext einer zyklischen Task (<code>FrIf_MainFunction</code>). Um den FlexRay-Buszyklus nicht zu blockieren, muss die PDU-Kopieroperation atomar und minimal gehalten werden; rechenintensive XCP-Befehle (z. B. Flash-Programmierung) müssen entkoppelt in der <code>Xcp_MainFunction()</code> abgearbeitet werden.</li>\n<li><strong>Konfigurationsbindung:</strong> In der AUTOSAR-Konfiguration (<code>EcucPostBuildType</code> / XML) muss die vom <code>FrIf</code> gemappte PDU als Rx-Referenz exakt auf die konfigurierte <code>XcpRxPduId</code> abgestimmt sein (<code>FrIfRxPduUserRxIndicationUL = XCP</code>).</li>\n</ul>"}, {"id": "FIG-00828d01cc1db4e1", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Schichtenarchitektur im Kommunikations- und Diagnose-Stack.</li>\n<li><strong>Funktionale Einordnung:</strong> Standardisierte PDU-Empfangskette des XCP-Moduls über das FlexRay-Interface (<code>FrIf</code>) und den PDU-Router (<code>PduR</code> bzw. <code>LSduR</code>). Visualisiert die synchrone Weiterleitung einer eingehenden FlexRay-PDU (XCP CTO/DTO) vom FlexRay-Interface über den PDU-Router an die FlexRay-Transport-Layer-Instanz des XCP-Moduls (<code>XcpOnFr</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Instanzen (Lifelines):</strong></li>\n<li><code>«module» FrIf</code>: FlexRay Interface (Communication Hardware Abstraction Layer). Agiert als Sender der Empfangsanzeige bei Eintreffen eines FlexRay-Frames bzw. einer LPDU.</li>\n<li><code>PduR - LSduR</code>: PDU Router / Lower-layer SDU Router (Communication Services Layer). Dient als vermittelnde Routing-Instanz zwischen Interface-Schicht und oberen Kommunikationsmodulen.</li>\n<li><code>XcpOnFr: Xcp</code>: XCP-Modul bzw. transportlayerspezifische Instanz für FlexRay (Services Layer / Complex Drivers). Empfänger der weitergeleiteten XCP-PDU.</li>\n<li><strong>Schnittstellen & Interaktionen:</strong></li>\n<li><code>LSduR_FrIfRxIndication()</code>: Synchroner Aufruf des FlexRay-Interfaces an das LSduR-Submodul des PduR zur Signalisierung einer empfangenen SDU.</li>\n<li><code>Xcp_RxIndication()</code>: Synchroner Callback des PduR an das XCP-Modul zur Übergabe der empfangenen PDU an den XCP-Protokoll-Stack.</li>\n<li>Synchrone Rückkehrpfade: Unbeschriftete Kontrollflussrückgaben von <code>XcpOnFr</code> an <code>PduR - LSduR</code> sowie von <code>PduR - LSduR</code> an <code>FrIf</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>FrIf</code> stellt das Vorliegen einer für XCP bestimmten PDU fest (z. B. im Rahmen von <code>FrIf_MainFunction_RouteRx()</code> oder eines Rx-Interrupt-Handlings).</li>\n<li><strong>Indikation an PduR:</strong> <code>FrIf</code> ruft synchron <code>LSduR_FrIfRxIndication()</code> auf der Instanz <code>PduR - LSduR</code> auf.</li>\n<li><strong>Routing an XCP:</strong> <code>PduR - LSduR</code> leitet den Empfang synchron über <code>Xcp_RxIndication()</code> an <code>XcpOnFr: Xcp</code> weiter.</li>\n<li><strong>Verarbeitung:</strong> <code>XcpOnFr</code> verarbeitet die übergebene PDU synchron bzw. übernimmt diese in den internen Stack.</li>\n<li><strong>Rückkehr:</strong> Der Kontrollfluss kehrt über gestrichelte Rückkehrkanten synchron von <code>XcpOnFr: Xcp</code> zu <code>PduR - LSduR</code> und anschließend von <code>PduR - LSduR</code> zu <code>FrIf</code> zurück, wodurch der Puffer im FlexRay-Treiber freigegeben wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur-Entkopplung:</strong> Die Kommunikation zwischen <code>FrIf</code> und <code>XcpOnFr</code> ist über den PDU-Router (<code>PduR</code>) entkoppelt. Das XCP-Modul nutzt die standardisierte Empfangsschnittstelle <code>Xcp_RxIndication()</code>.</li>\n<li><strong>Konfigurationsbindung:</strong> In der AUTOSAR-Konfiguration (<code>ECUC</code>) wird die vom <code>FrIf</code> empfangene PDU im PDU-Router über entsprechende Routing-Pfade (<code>PduRRoutingPath</code>) auf die Ziel-PDU des XCP-Moduls gemappt. Die obere Schichtreferenz im FlexRay Interface verweist auf den PDU-Router (<code>FrIfRxPduUserRxIndicationUL = PDUR</code>).</li>\n<li><strong>Ausführungskontext & Latenz:</strong> Der synchrone Aufruf durchläuft mehrere Architekturschichten (<code>FrIf</code> -> <code>PduR</code> -> <code>Xcp</code>). Die Ausführung erfolgt blockierend im Kontext des FlexRay-Interface-Aufrufers (Interrupt oder zyklische Task). Zur Vermeidung von Timing-Verletzungen im FlexRay-Buszyklus müssen PDU-Kopier- und Weiterleitungsschritte minimal gehalten und zeitintensive Verarbeitungen asynchron entkoppelt werden.</li>\n</ul>"}, {"id": "FIG-c707d64b95854b3e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (CP), Schichtenarchitektur im Kommunikations- und Diagnose-Stack.</li>\n<li><strong>Funktionale Einordnung:</strong> Standardisierte PDU-Empfangskette des XCP-Moduls über das FlexRay-Interface (<code>FrIf</code>) und den PDU-Router (<code>PduR</code> bzw. <code>LSduR</code>). Visualisiert die synchrone Weiterleitung einer eingehenden FlexRay-PDU (XCP CTO/DTO) vom FlexRay-Interface über den PDU-Router an die FlexRay-Transport-Layer-Instanz des XCP-Moduls (<code>XcpOnFr</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte Instanzen (Lifelines):</strong></li>\n<li><code>«module» FrIf</code>: FlexRay Interface (Communication Hardware Abstraction Layer). Agiert als Sender der Empfangsanzeige bei Eintreffen eines FlexRay-Frames bzw. einer LPDU.</li>\n<li><code>PduR - LSduR</code>: PDU Router / Lower-layer SDU Router (Communication Services Layer). Dient als vermittelnde Routing-Instanz zwischen Interface-Schicht und oberen Kommunikationsmodulen.</li>\n<li><code>XcpOnFr: Xcp</code>: XCP-Modul bzw. transportlayerspezifische Instanz für FlexRay (Services Layer / Complex Drivers). Empfänger der weitergeleiteten XCP-PDU.</li>\n<li><strong>Schnittstellen & Interaktionen:</strong></li>\n<li><code>LSduR_FrIfRxIndication()</code>: Synchroner Aufruf des FlexRay-Interfaces an das LSduR-Submodul des PduR zur Signalisierung einer empfangenen SDU.</li>\n<li><code>Xcp_RxIndication()</code>: Synchroner Callback des PduR an das XCP-Modul zur Übergabe der empfangenen PDU an den XCP-Protokoll-Stack.</li>\n<li>Synchrone Rückkehrpfade: Unbeschriftete Kontrollflussrückgaben von <code>XcpOnFr</code> an <code>PduR - LSduR</code> sowie von <code>PduR - LSduR</code> an <code>FrIf</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>FrIf</code> stellt das Vorliegen einer für XCP bestimmten PDU fest (z. B. im Rahmen von <code>FrIf_MainFunction_RouteRx()</code> oder eines Rx-Interrupt-Handlings).</li>\n<li><strong>Indikation an PduR:</strong> <code>FrIf</code> ruft synchron <code>LSduR_FrIfRxIndication()</code> auf der Instanz <code>PduR - LSduR</code> auf.</li>\n<li><strong>Routing an XCP:</strong> <code>PduR - LSduR</code> leitet den Empfang synchron über <code>Xcp_RxIndication()</code> an <code>XcpOnFr: Xcp</code> weiter.</li>\n<li><strong>Verarbeitung:</strong> <code>XcpOnFr</code> verarbeitet die übergebene PDU synchron bzw. übernimmt diese in den internen Stack.</li>\n<li><strong>Rückkehr:</strong> Der Kontrollfluss kehrt über gestrichelte Rückkehrkanten synchron von <code>XcpOnFr: Xcp</code> zu <code>PduR - LSduR</code> und anschließend von <code>PduR - LSduR</code> zu <code>FrIf</code> zurück, wodurch der Puffer im FlexRay-Treiber freigegeben wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur-Entkopplung:</strong> Die Kommunikation zwischen <code>FrIf</code> und <code>XcpOnFr</code> ist über den PDU-Router (<code>PduR</code>) entkoppelt. Das XCP-Modul nutzt die standardisierte Empfangsschnittstelle <code>Xcp_RxIndication()</code>.</li>\n<li><strong>Konfigurationsbindung:</strong> In der AUTOSAR-Konfiguration (<code>ECUC</code>) wird die vom <code>FrIf</code> empfangene PDU im PDU-Router über entsprechende Routing-Pfade (<code>PduRRoutingPath</code>) auf die Ziel-PDU des XCP-Moduls gemappt. Die obere Schichtreferenz im FlexRay Interface verweist auf den PDU-Router (<code>FrIfRxPduUserRxIndicationUL = PDUR</code>).</li>\n<li><strong>Ausführungskontext & Latenz:</strong> Der synchrone Aufruf durchläuft mehrere Architekturschichten (<code>FrIf</code> -> <code>PduR</code> -> <code>Xcp</code>). Die Ausführung erfolgt blockierend im Kontext des FlexRay-Interface-Aufrufers (Interrupt oder zyklische Task). Zur Vermeidung von Timing-Verletzungen im FlexRay-Buszyklus müssen PDU-Kopier- und Weiterleitungsschritte minimal gehalten und zeitintensive Verarbeitungen asynchron entkoppelt werden.</li>\n</ul>"}], "trans": [{"from": "FIG-810fd0bcc4cdbc54", "to": "FIG-c7636a81bae2763c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c7636a81bae2763c", "to": "FIG-9981e87515a3a421", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9981e87515a3a421", "to": "FIG-0c98b8e590b59800", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0c98b8e590b59800", "to": "FIG-00828d01cc1db4e1", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Lifeline <code>FrIf: FrIf</code>: Ersetzt durch Stereotyp <code>«module» FrIf</code>.</li>\n<li>Instanz <code>PduR - LSduR</code>: Als vermittelnde Routing-Lifeline zwischen <code>FrIf</code> und <code>XcpOnFr: Xcp</code> eingefügt.</li>\n<li>Empfangsinteraktion: Direkter synchroner Aufruf <code>Xcp_FrIfRxIndication(PduIdType, const uint8*)</code> ersetzt durch zweistufige Signalisierung via PDU-Router:</li>\n<li><code>LSduR_FrIfRxIndication()</code> von <code>FrIf</code> an <code>PduR - LSduR</code>.</li>\n<li><code>Xcp_RxIndication()</code> von <code>PduR - LSduR</code> an <code>XcpOnFr: Xcp</code>.</li>\n<li>Parameterliste: Bei den Interaktionen <code>LSduR_FrIfRxIndication()</code> und <code>Xcp_RxIndication()</code> entfällt die explizite Darstellung der Parameter (<code>PduIdType, const uint8*</code>).</li>\n<li>Interne Operation: Der interne Selbstaufruf <code>Copy PDU to internal location and process PDU()</code> an <code>XcpOnFr</code> entfällt.</li>\n<li>Rückkehrkanten: Die synchrone Rückkehrkante <code>Xcp_FrIfRxIndication()</code> an <code>FrIf</code> ersetzt durch unbeschriftete synchrone Rückkehrkanten von <code>XcpOnFr</code> an <code>PduR - LSduR</code> sowie von <code>PduR - LSduR</code> an <code>FrIf</code>.</li>\n</ul>"}, {"from": "FIG-00828d01cc1db4e1", "to": "FIG-c707d64b95854b3e", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
